window.QUESTION_TOPICS = window.QUESTION_TOPICS || {};
window.QUESTION_TOPICS["content/06_tools_build_debug/01_build.md"] = [{"id":"content/06_tools_build_debug/01_build.md:e7589783c827bbd3:1","question":"<p>(L1, T) Какие стадии включает compilation pipeline?</p>\n","answer":"<p><strong>Ответ:</strong> Классический пайплайн сборки C/C++ включает 4 последовательные стадии: препроцессинг (preprocessing), трансляция/компиляция в ассемблер (compilation), ассемблирование в машинный код (assembly) и компоновка/линковка (linking).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>main.c -&gt; [ Препроцессор (cpp) ] -&gt; main.i\n       -&gt; [ Компилятор (cc1) ]    -&gt; main.s\n       -&gt; [ Ассемблер (as) ]     -&gt; main.o\n       -&gt; [ Линкер (ld) ]        -&gt; a.out\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html?utm_source=gemini\">GCC Online Docs: Overall Options</a></p>\n","group":"L1","line":6},{"id":"content/06_tools_build_debug/01_build.md:8cb775a2627f9d1c:1","question":"<p>(L1, T) Что делает препроцессор?</p>\n","answer":"<p><strong>Ответ:</strong> Препроцессор выполняет текстовые преобразования до синтаксического анализа: подставляет содержимое файлов по <code>#include</code>, раскрывает макроопределения <code>#define</code>, удаляет комментарии и отсекает неактивные ветки условной компиляции (<code>#ifdef</code>, <code>#if</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">#define VALUE 42\nint x = VALUE; // Препроцессор заменит на: int x = 42;\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://en.cppreference.com/w/cpp/language/translation_phases?utm_source=gemini\">cppreference: Phases of translation</a></p>\n","group":"L1","line":21},{"id":"content/06_tools_build_debug/01_build.md:91f4568d1dab1153:1","question":"<p>(L1, T) В чем разница между <code>.c</code> и <code>.o</code> файлами?</p>\n","answer":"<p><strong>Ответ:</strong> Файл <code>.c</code> — это исходный человекочитаемый текст программы. Файл <code>.o</code> (object file) — сгенерированный машинный двоичный код для конкретной архитектуры с незаполненными адресами внешних вызовов (relocations) и таблицей символов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">file main.c # C source, ASCII text\nfile main.o # ELF 64-bit LSB relocatable, x86-64\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/ch4.intro.html?utm_source=gemini\">System V Application Binary Interface (GABI)</a></p>\n","group":"L1","line":34},{"id":"content/06_tools_build_debug/01_build.md:9cf7a08da04346e2:1","question":"<p>(L1, T) Что делает компилятор?</p>\n","answer":"<p><strong>Ответ:</strong> Компилятор преобразует единицу трансляции в ассемблерный код или промежуточное представление (IR): выполняет лексический, синтаксический и семантический разбор, строит AST-дерево и производит оптимизации (inlining, векторизация, unrolling).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Получение ассемблерного кода:\ngcc -S -O2 main.c -o main.s\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.aosabook.org/en/llvm.html?utm_source=gemini\">LLVM Compiler Architecture Overview</a></p>\n","group":"L1","line":47},{"id":"content/06_tools_build_debug/01_build.md:73fd05bc9d2a9df4:1","question":"<p>(L1, T) Что делает линкер?</p>\n","answer":"<p><strong>Ответ:</strong> Линкер связывает независимые объектные файлы (<code>.o</code>) и библиотеки (<code>.a</code>, <code>.so</code>) в исполняемый бинарник или разделяемую библиотеку, разрешая внешние ссылки на функции/переменные и выполняя релокацию адресов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">ld -o app main.o utils.o -lc\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.iecc.com/linker/?utm_source=gemini\">Levine, J. R. &quot;Linkers and Loaders&quot;</a></p>\n","group":"L1","line":60},{"id":"content/06_tools_build_debug/01_build.md:cdd38eeb1c79cbdd:1","question":"<p>(L1, T) Что такое <code>#include</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Директива препроцессора, выполняющая физическую копипасту указанного файла целиком в текущую позицию исходного кода до начала компиляции.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">#include &quot;header.h&quot; // Всё содержимое header.h вставляется прямо сюда\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://en.cppreference.com/w/cpp/preprocessor/include?utm_source=gemini\">cppreference: Source file inclusion</a></p>\n","group":"L1","line":72},{"id":"content/06_tools_build_debug/01_build.md:266cdb0f91f77dc2:1","question":"<p>(L1, T) Разница между <code>&lt;...&gt;</code> и <code>&quot;...&quot;</code>?</p>\n","answer":"<p><strong>Ответ:</strong> При <code>#include &lt;...&gt;</code> компилятор ищет заголовок строго в стандартных системных директориях и путях, указанных через <code>-I</code>. При <code>#include &quot;...&quot;</code> поиск начинается сначала с каталога текущего исходного файла, и лишь затем переходит к системным путям.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">#include &lt;vector&gt;   // Системный STL заголовок\n#include &quot;my_cfg.h&quot; // Локальный заголовок в папке с кодом\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/cpp/Search-Path.html?utm_source=gemini\">GCC Online Docs: Search Path</a></p>\n","group":"L1","line":84},{"id":"content/06_tools_build_debug/01_build.md:a2dbbc1b4cb1db05:1","question":"<p>(L1, T) Что такое header file?</p>\n","answer":"<p><strong>Ответ:</strong> Текстовый файл (обычно <code>.h</code> / <code>.hpp</code>), содержащий объявления типов, структур, классов, прототипов функций и констант, используемый для разделения публичного интерфейса модуля и его приватной реализации.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">// math_utils.h\n#pragma once\nint add(int a, int b); // Интерфейс без тела\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines?utm_source=gemini#sf1-keep-declarations-in-header-files\">C++ Core Guidelines: SF.1</a></p>\n","group":"L1","line":97},{"id":"content/06_tools_build_debug/01_build.md:b515427f9d8e0a09:1","question":"<p>(L1, T) Что такое object file?</p>\n","answer":"<p><strong>Ответ:</strong> Промежуточный бинарный файл формата ELF/Mach-O/COFF, содержащий секции машинного кода (<code>.text</code>), инициализированных данных (<code>.data</code>), таблицу символов (<code>.symtab</code>) и директивы перемещения адресов для линкера.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -c worker.c -o worker.o # Получение object file\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/ch4.intro.html?utm_source=gemini\">System V ABI: Object Files</a></p>\n","group":"L1","line":111},{"id":"content/06_tools_build_debug/01_build.md:bae37de50ab8364c:1","question":"<p>(L1, P) Как скомпилировать файл вручную через <code>gcc</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Компиляция без линковки выполняется флагом <code>-c</code>, полная сборка в исполняемый файл — прямым вызовом компилятора с указанием выходного флага <code>-o</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -Wall -Wextra -O2 -c main.c -o main.o\ngcc main.o -o my_app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Invoking-GCC.html?utm_source=gemini\">GCC Command Options</a></p>\n<hr />\n","group":"L1","line":123},{"id":"content/06_tools_build_debug/01_build.md:647fae1416d5d2a4:1","question":"<p>(L2, T) Что такое translation unit?</p>\n","answer":"<p><strong>Ответ:</strong> Единица трансляции (Translation Unit) — базовый входной поток данных для компилятора, получаемый после обработки одного <code>.c</code>/<code>.cpp</code> файла препроцессором со всеми раскрытыми заголовками и макросами.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Получение единицы трансляции:\ngcc -E main.c -o main.i\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://en.cppreference.com/w/cpp/language/translation_phases?utm_source=gemini\">cppreference: Translation units</a></p>\n","group":"L2","line":140},{"id":"content/06_tools_build_debug/01_build.md:dbe8ff25998a5ed3:1","question":"<p>(L2, T) Что такое symbol table?</p>\n","answer":"<p><strong>Ответ:</strong> Таблица символов — секция внутри объектного файла, связывающая идентификаторы функций и переменных с их типами, областями видимости (local/global) и адресами со смещением относительно секций.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">readelf -s main.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/ch4.symtab.html?utm_source=gemini\">System V ABI: Symbol Table</a></p>\n","group":"L2","line":153},{"id":"content/06_tools_build_debug/01_build.md:226dd57b8af38047:1","question":"<p>(L2, T) Что такое relocation?</p>\n","answer":"<p><strong>Ответ:</strong> Процесс подстановки окончательных абсолютных или относительных адресов в машинные команды и структуры данных, выполняемый линкером после объединения секций и фиксации базовых адресов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Просмотр записей релокации:\nreadelf -r main.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://eli.thegreenplace.net/2011/08/25/load-time-relocation-of-shared-libraries?utm_source=gemini\">Eli Bendersky: How Linkers Work</a></p>\n","group":"L2","line":165},{"id":"content/06_tools_build_debug/01_build.md:4da59bb68077d2b0:1","question":"<p>(L2, T) Что такое ODR?</p>\n","answer":"<p><strong>Ответ:</strong> One Definition Rule — правило одного определения в C++, запрещающее более одного определения не-<code>inline</code> переменной/функции в программе и требующее эквивалентности дублирующихся определений типов в разных translation units.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cpp\">// a.cpp: int id = 1;\n// b.cpp: int id = 2; // Нарушение ODR при линковке\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://en.cppreference.com/w/cpp/language/definition?utm_source=gemini#One_Definition_Rule\">cppreference: One Definition Rule</a></p>\n","group":"L2","line":178},{"id":"content/06_tools_build_debug/01_build.md:7780bf37392f03d0:1","question":"<p>(L2, P) Как посмотреть результат препроцессинга?</p>\n","answer":"<p><strong>Ответ:</strong> Флаг <code>-E</code> останавливает компилятор сразу после работы препроцессора и выводит чистый код в стандартный поток или файл.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -E -P main.c -o preprocessed.c\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Preprocessor-Options.html?utm_source=gemini\">GCC Options Controlling the Preprocessor</a></p>\n","group":"L2","line":191},{"id":"content/06_tools_build_debug/01_build.md:f917904cc578b952:1","question":"<p>(L2, P) Как собрать <code>.o</code>, а затем бинарь вручную?</p>\n","answer":"<p><strong>Ответ:</strong> Сначала компилируются исходники во флаге <code>-c</code>, затем объектные модули сводятся вызовом компилятора-драйвера в единый бинарник.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -c a.c -o a.o\ngcc -c b.c -o b.o\ngcc a.o b.o -o final_app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/?utm_source=gemini\">GCC Online Manual</a></p>\n","group":"L2","line":203},{"id":"content/06_tools_build_debug/01_build.md:aa2709305fa2536c:1","question":"<p>(L2, D) Почему возникает <code>undefined reference</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Ошибка линкера, означающая, что символ был объявлен и использован в коде, но ни один переданный объектный файл или библиотека не содержит его фактического определения в секциях кода/данных.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># undefined reference to 'calculate_sum'\n# Причина: забыли скомпилировать math.c или передать math.o линкеру\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/wiki/VerboseDiagnostics?utm_source=gemini#undefined_reference\">GCC Wiki: Verbose Diagnostics</a></p>\n","group":"L2","line":217},{"id":"content/06_tools_build_debug/01_build.md:eb36abcdaa9d0838:1","question":"<p>(L2, D) Почему возникает <code>multiple definition</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Ошибка линкера, означающая, что один и тот же сильный глобальный символ (функция или глобальная переменная без <code>inline</code>/<code>static</code>) определен более чем в одном <code>.o</code> файле проекта.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">// header.h\nint counter = 0; // Определение в хедере! При включении в 2 .c файла даст multiple definition.\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/ld/Options.html?utm_source=gemini\">GNU ld: Duplicate symbols</a></p>\n","group":"L2","line":230},{"id":"content/06_tools_build_debug/01_build.md:96cc3f9eb9db8055:1","question":"<p>(L2, T) Как компилятор обрабатывает inline?</p>\n","answer":"<p><strong>Ответ:</strong> Для оптимизатора <code>inline</code> — это эвристическая подсказка встроить тело функции по месту вызова без <code>call</code>. Для линкера — указание пометить символ как слабый (weak/linkonce), чтобы объединить идентичные копии определений из разных <code>.o</code> файлов в одну.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">inline int max(int a, int b) { return a &gt; b ? a : b; }\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://en.cppreference.com/w/cpp/language/inline?utm_source=gemini\">cppreference: inline specifier</a></p>\n","group":"L2","line":243},{"id":"content/06_tools_build_debug/01_build.md:177b44b8a63eb28e:1","question":"<p>(L2, T) Что такое debug symbols?</p>\n","answer":"<p><strong>Ответ:</strong> Метаданные (форматы DWARF в Linux, PDB в Windows), сохраняющие таблицы соответствия смещений инструкций строкам исходного кода, именам локальных переменных и типам для дебаггеров (GDB/LLDB).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -g -O0 main.c -o app_debug # Флаг -g внедряет секции .debug_*\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://dwarfstd.org/?utm_source=gemini\">DWARF Debugging Standard</a></p>\n<hr />\n","group":"L2","line":255},{"id":"content/06_tools_build_debug/01_build.md:c0f5499c243b6588:1","question":"<p>(L3, T) Как устроен ELF object file?</p>\n","answer":"<p><strong>Ответ:</strong> Структура ELF включает ELF Header (магическое число, архитектура, ABI), Program Header Table (для сегментов загрузки в память), секции (код, данные, метаданные) и Section Header Table (описывает границы секций для компоновщика).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>[ ELF Header ]\n[ .text (Код) ]\n[ .data (Инициализированные данные) ]\n[ .bss (Нули) ]\n[ .symtab (Символы) ]\n[ Section Header Table ]\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/ch4.intro.html?utm_source=gemini\">System V Application Binary Interface (GABI)</a></p>\n","group":"L3","line":271},{"id":"content/06_tools_build_debug/01_build.md:7dcc2942195f8b69:1","question":"<p>(L3, T) Что такое sections (.text, .data, .bss)?</p>\n","answer":"<p><strong>Ответ:</strong> <code>.text</code> — сегмент неизменяемых исполняемых инструкций CPU; <code>.data</code> — сегмент глобальных/статических инициализированных переменных; <code>.bss</code> — сегмент неинициализированных нулей (не занимает места в бинарнике на диске, расширяется ОС при запуске).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">int a = 10;   // .data\nint b;        // .bss\nvoid f() {}   // .text\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://csapp.cs.cmu.edu/?utm_source=gemini\">CS:APP (Bryant &amp; O'Hallaron): Linking</a></p>\n","group":"L3","line":288},{"id":"content/06_tools_build_debug/01_build.md:c1e3123798c22d8f:1","question":"<p>(L3, T) Что такое GOT/PLT?</p>\n","answer":"<p><strong>Ответ:</strong> Механизм для Position Independent Code (PIC): PLT (Procedure Linkage Table) — массив инструкций-трамплинов для вызова внешних функций; GOT (Global Offset Table) — таблица абсолютных адресов данных и функций в памяти, заполняемая динамическим линкером при старте или лениво.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Вызов printf -&gt; PLT[printf] -&gt; читает GOT[printf] -&gt; переход в libc.so\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.airs.com/blog/archives/41?utm_source=gemini\">Ian Lance Taylor: Linkers (Part 4 - GOT and PLT)</a></p>\n","group":"L3","line":302},{"id":"content/06_tools_build_debug/01_build.md:ec62c0224a619d7f:1","question":"<p>(L3, T) Как работает dynamic linker?</p>\n","answer":"<p><strong>Ответ:</strong> Системная программа (<code>ld.so</code>), запускаемая ядром при выполнении бинарника: считывает секцию <code>.dynamic</code>, загружает зависимые <code>.so</code> библиотеки через <code>mmap</code>, выполняет релокацию адресов в GOT и передает управление в <code>_start</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">/lib64/ld-linux-x86-64.so.2 ./my_program\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man8/ld.so.8.html?utm_source=gemini\">Linux man-pages: ld.so(8)</a></p>\n","group":"L3","line":314},{"id":"content/06_tools_build_debug/01_build.md:b5790de4e2d2d4f1:1","question":"<p>(L3, P) Как посмотреть symbols через <code>nm</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Утилита <code>nm</code> выводит таблицу символов файла с их типами (<code>T</code> — глобальный код, <code>U</code> — неразрешенный внешний символ, <code>D</code> — инициализированные данные).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">nm -C my_file.o\n# 0000000000000000 T calculate\n#                  U printf\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/nm.html?utm_source=gemini\">GNU Binutils: nm manual</a></p>\n","group":"L3","line":326},{"id":"content/06_tools_build_debug/01_build.md:64f2161641eb2678:1","question":"<p>(L3, P) Как анализировать бинарь через <code>readelf</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>readelf</code> позволяет инспектировать заголовки, секции, сегменты и зависимости ELF-файла без привлечения библиотек разбора.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">readelf -h app  # ELF Header\nreadelf -d app  # Dynamic section (.dynamic, RPATH, NEEDED)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man1/readelf.1.html?utm_source=gemini\">Linux man-pages: readelf(1)</a></p>\n","group":"L3","line":340},{"id":"content/06_tools_build_debug/01_build.md:21056e3cc2e2fd23:1","question":"<p>(L3, D) Почему бинарь падает при запуске, хотя линковка успешна?</p>\n","answer":"<p><strong>Ответ:</strong> Причины: не найдена зависимая <code>.so</code> динамическим загрузчиком; несовпадение ABI версий библиотек (бинарная несовместимость); краш в глобальных конструкторах (<code>.init_array</code>) до вызова <code>main()</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># error while loading shared libraries: libfoo.so: cannot open shared object file\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man8/ld.so.8.html?utm_source=gemini\">Dynamic Linker Search Path Rules</a></p>\n","group":"L3","line":353},{"id":"content/06_tools_build_debug/01_build.md:4ba82369eab5ead2:1","question":"<p>(L3, T) Что такое weak symbols?</p>\n","answer":"<p><strong>Ответ:</strong> Символы с пониженным приоритетом при компоновке: линкер разрешает их переопределение сильным символом без ошибки дублирования, а если определение отсутствует вовсе, адрес символа обнуляется.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">__attribute__((weak)) void default_impl() {}\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Common-Function-Attributes.html?utm_source=gemini#index-weak-function-attribute\">GCC Variable and Function Attributes: weak</a></p>\n","group":"L3","line":365},{"id":"content/06_tools_build_debug/01_build.md:86860854e4b7742d:1","question":"<p>(L3, T) Как работает symbol resolution?</p>\n","answer":"<p><strong>Ответ:</strong> Линкер сканирует входные файлы слева направо, ведя наборы определенных (D) и неопределенных (U) символов. Встретив сильный символ, линкер закрывает ссылку; если встречает дубль сильного — падает с ошибкой; слабые символы перезаписываются сильными.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Strong + Strong = Error (multiple definition)\nStrong + Weak   = Strong побеждает\nWeak + Weak     = Линкер произвольно выбирает первый\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://csapp.cs.cmu.edu/?utm_source=gemini\">CS:APP Chapter 7: Symbol Resolution</a></p>\n","group":"L3","line":377},{"id":"content/06_tools_build_debug/01_build.md:7208b7739c200214:1","question":"<p>(L3, D) Почему порядок линковки <code>.a</code> важен?</p>\n","answer":"<p><strong>Ответ:</strong> Статические библиотеки (<code>.a</code>) сканируются строго в порядке указания в командной строке. Линкер извлекает из <code>.a</code> только те <code>.o</code>, которые закрывают <em>уже накопленные</em> к этому моменту неразрешенные символы. Если библиотека <code>B</code> зависит от <code>A</code>, но указана до нее, возникнет <code>undefined reference</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Ошибка:\ngcc -lmylib main.o -o app\n# Корректно (зависимый идет перед поставщиком):\ngcc main.o -lmylib -o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://eli.thegreenplace.net/2013/07/09/library-order-in-static-linking?utm_source=gemini\">Eli Bendersky: Library order in static linking</a></p>\n<hr />\n","group":"L3","line":391},{"id":"content/06_tools_build_debug/01_build.md:f1d716b7eebee73a:1","question":"<p>(L4, T) Как реализована lazy binding?</p>\n","answer":"<p><strong>Ответ:</strong> При первом вызове функции через PLT управление прыгает в резолвер динамического линкера (<code>_dl_runtime_resolve</code>), передавая ID символа и релокации. Линкер вычисляет адрес функции, прописывает его напрямую в GOT-ячейку, и все последующие вызовы минуют линкер.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Call foo@plt -&gt; GOT указывает на вторую строчку PLT -&gt; push ID -&gt; jump _dl_runtime_resolve -&gt; GOT обновлен!\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.akkadia.org/drepper/dsohowto.pdf?utm_source=gemini\">Ulrich Drepper: How To Write Shared Libraries</a></p>\n","group":"L4","line":410},{"id":"content/06_tools_build_debug/01_build.md:b16c362405e2b4ec:1","question":"<p>(L4, T) Как работает relocation на runtime?</p>\n","answer":"<p><strong>Ответ:</strong> При загрузке PIC-библиотеки загрузчик смещает адреса по базовому смещению (ASLR base). Для символов данных он правит записи GOT по типу <code>R_X86_64_RELATIVE</code> или <code>R_X86_64_GLOB_DAT</code>, сопоставляя их с таблицей <code>.dynsym</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">readelf -r libfoo.so # Типы релокаций времени выполнения\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/ch5.dynamic.html?utm_source=gemini\">System V Application Binary Interface (Dynamic Linking)</a></p>\n","group":"L4","line":422},{"id":"content/06_tools_build_debug/01_build.md:81f5486c6ec802c8:1","question":"<p>(L4, S) Как минимизировать symbol conflicts в large-scale системе?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Скрывать приватные символы по умолчанию флагом <code>-fvisibility=hidden</code>; 2) Использовать Version Scripts для экспорта только официального API; 3) Изолировать динамические плагины флагом <code>RTLD_LOCAL</code> при <code>dlopen</code>; 4) Использовать namespaces и anonymous namespaces.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>// version_script.map\nLIB_1.0 {\n    global: public_api_*;\n    local: *;\n};\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/wiki/Visibility?utm_source=gemini\">GCC Wiki: Visibility</a></p>\n","group":"L4","line":434},{"id":"content/06_tools_build_debug/01_build.md:32666fb87c25565b:1","question":"<p>(L4, T) Как реализован dynamic loader в Linux?</p>\n","answer":"<p><strong>Ответ:</strong> <code>ld-linux.so</code> — это самостоятельный позиционно-независимый исполняемый ELF, стартующий без внешних библиотек. Он сам выполняет собственные базовые релокации (bootstrap), читает вспомогательный вектор ядра (Auxiliary Vector <code>auxv</code>), парсит заголовки программы, строит граф DSOs (BFS/DFS) и выполняет relocations.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Просмотр шагов загрузчика:\nLD_DEBUG=all ./my_app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/git/?p=glibc.git;a=blob;f=elf/rtld.c?utm_source=gemini\">Glibc Source: elf/rtld.c</a></p>\n","group":"L4","line":450},{"id":"content/06_tools_build_debug/01_build.md:84b7c87bbe2da903:1","question":"<p>(L4, D) Как диагностировать subtle ABI mismatch?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Сравнить дампы памяти структур через <code>pahole</code> или <code>clang -fdump-record-layouts</code>; 2) Сравнить бинарный ABI через инструмент <code>abidiff</code> (libabigail); 3) Проверить расхождение флагов типа <code>-D_GLIBCXX_USE_CXX11_ABI</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">abidiff libold.so libnew.so # Подсветит измененные размеры структур и vtable\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/libabigail/?utm_source=gemini\">Libabigail: ABI Generic Analysis and Instrumentation Library</a></p>\n<hr />\n","group":"L4","line":463},{"id":"content/06_tools_build_debug/01_build.md:9d4016d8691fc67d:1","question":"<p>(L1, T) Что такое static library?</p>\n","answer":"<p><strong>Ответ:</strong> Статическая библиотека — это архив скомпилированных объектных файлов (<code>.o</code>), запакованных в один файл утилитой <code>ar</code>, код которых копируется линкером в итоговый исполняемый файл на этапе сборки.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">ar rcs libtools.a tool1.o tool2.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/ar.html?utm_source=gemini\">GNU Binutils: ar</a></p>\n","group":"L1","line":481},{"id":"content/06_tools_build_debug/01_build.md:a73f2e8b6eb996a1:1","question":"<p>(L1, T) Что такое shared library?</p>\n","answer":"<p><strong>Ответ:</strong> Разделяемая (динамическая) библиотека — бинарный файл (<code>.so</code> / <code>.dll</code>), загружаемый в оперативную память один раз и используемый множеством одновременно работающих процессов за счет разделения страниц виртуальной памяти кода.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -shared -fPIC math.c -o libmath.so\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://tldp.org/HOWTO/Program-Library-HOWTO/shared-libraries.html?utm_source=gemini\">Linux Program Library HOWTO</a></p>\n","group":"L1","line":493},{"id":"content/06_tools_build_debug/01_build.md:ff05b77303676206:1","question":"<p>(L1, T) Разница <code>.a</code> vs <code>.so</code>?</p>\n","answer":"<p><strong>Ответ:</strong> <code>.a</code> внедряется в тело бинарника на этапе сборки (раздувает размер, автономен); <code>.so</code> подключается загрузчиком при старте программы (экономит память, но требует наличия файла в системе).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc main.o libfoo.a -o app_static # .a\ngcc main.o -L. -lfoo -o app_dyn   # .so\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.iecc.com/linker/?utm_source=gemini\">Levine, J. R. Linkers and Loaders</a></p>\n","group":"L1","line":505},{"id":"content/06_tools_build_debug/01_build.md:556c0899aa7d570e:1","question":"<p>(L1, P) Как собрать static library?</p>\n","answer":"<p><strong>Ответ:</strong> Скомпилировать файлы в <code>.o</code> и упаковать архиватором <code>ar</code> с ключами <code>rcs</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -c util.c -o util.o\nar rcs libutil.a util.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/binutils/ar.html?utm_source=gemini\">GNU ar documentation</a></p>\n","group":"L1","line":518},{"id":"content/06_tools_build_debug/01_build.md:93c19731da2f92c1:1","question":"<p>(L1, P) Как собрать shared library?</p>\n","answer":"<p><strong>Ответ:</strong> Скомпилировать код с флагом <code>-fPIC</code> (Position Independent Code) и слинковать с флагом <code>-shared</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -fPIC -c util.c -o util.o\ngcc -shared util.o -o libutil.so\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Link-Options.html?utm_source=gemini\">GCC Link Options (-shared)</a></p>\n<hr />\n","group":"L1","line":531},{"id":"content/06_tools_build_debug/01_build.md:04115f73cbcb1eca:1","question":"<p>(L2, T) Когда использовать static linking?</p>\n","answer":"<p><strong>Ответ:</strong> Когда критична портабельность и автономность развертывания (single binary deployment в Docker без зависимостей), когда недопустимы накладные расходы на запуск динамического линкера, или для предотвращения DLL hell.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -static main.c -o standalone_app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines?utm_source=gemini\">C++ Core Guidelines</a></p>\n","group":"L2","line":548},{"id":"content/06_tools_build_debug/01_build.md:b1add0c212c2000d:1","question":"<p>(L2, T) Когда использовать dynamic linking?</p>\n","answer":"<p><strong>Ответ:</strong> Когда код библиотеки используется многими процессами (экономия RAM и диска), для реализации модульной архитектуры плагинов, а также для возможности обновлять библиотеки безопасности без перекомпиляции основного ПО.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Обновление системной libssl.so закрывает уязвимость во всех приложениях сразу.\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.akkadia.org/drepper/dsohowto.pdf?utm_source=gemini\">Ulrich Drepper: How To Write Shared Libraries</a></p>\n","group":"L2","line":560},{"id":"content/06_tools_build_debug/01_build.md:63d5f33e608ebe2d:1","question":"<p>(L2, T) Что такое SONAME?</p>\n","answer":"<p><strong>Ответ:</strong> Логическое имя разделяемой библиотеки, прошиваемое внутрь нее линкером; указывает на совместимую версию ABI (например, <code>libcrypto.so.1.1</code>). Загрузчик ищет файл именно по SONAME, а не по физическому имени файла на диске.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc -shared -Wl,-soname,libfoo.so.1 -o libfoo.so.1.0.0 foo.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man8/ld.so.8.html?utm_source=gemini\">Linux man-pages: ld.so(8)</a></p>\n","group":"L2","line":572},{"id":"content/06_tools_build_debug/01_build.md:c5422dadde697267:1","question":"<p>(L2, P) Как посмотреть зависимости бинаря (<code>ldd</code>)?</p>\n","answer":"<p><strong>Ответ:</strong> Утилита <code>ldd</code> запускает динамический линкер в диагностическом режиме и выводит список всех найденных <code>.so</code> файлов и их адреса.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">ldd /bin/ls\n# libc.so.6 =&gt; /lib/x86_64-linux-gnu/libc.so.6 (0x00007f...)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man1/ldd.1.html?utm_source=gemini\">Linux man-pages: ldd(1)</a></p>\n","group":"L2","line":584},{"id":"content/06_tools_build_debug/01_build.md:7e84cf900f7d82b3:1","question":"<p>(L2, D) Почему не находится <code>.so</code> при запуске?</p>\n","answer":"<p><strong>Ответ:</strong> Директория с библиотекой не входит в стандартный путь поиска <code>ld.so</code>, не указана в переменной <code>LD_LIBRARY_PATH</code> или не прошита в заголовках бинарника через <code>rpath</code>/<code>runpath</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">./app: error while loading shared libraries: libfoo.so: cannot open shared object file\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://wiki.debian.org/RpathIssue?utm_source=gemini\">Debian Wiki: RpathIssue</a></p>\n","group":"L2","line":597},{"id":"content/06_tools_build_debug/01_build.md:fc76fc01f4baf4b8:1","question":"<p>(L2, T) Что такое LD_LIBRARY_PATH?</p>\n","answer":"<p><strong>Ответ:</strong> Переменная окружения, содержащая разделенный двоеточиями список каталогов, в которых динамический загрузчик ищет библиотеки до обращения к системным папкам (<code>/lib</code>, <code>/usr/lib</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">export LD_LIBRARY_PATH=/opt/custom_libs:$LD_LIBRARY_PATH\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man8/ld.so.8.html?utm_source=gemini\">Linux man-pages: ld.so(8)</a></p>\n","group":"L2","line":609},{"id":"content/06_tools_build_debug/01_build.md:e55c163f8bf2b84b:1","question":"<p>(L2, T) Что такое rpath?</p>\n","answer":"<p><strong>Ответ:</strong> Запись <code>DT_RPATH</code> внутри секции <code>.dynamic</code> ELF-бинарника, жестко кодирующая пути поиска библиотек во время сборки; имеет приоритет над переменной <code>LD_LIBRARY_PATH</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc main.o -Wl,-rpath,/custom/path -L. -lfoo -o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://refspecs.linuxfoundation.org/elf/gabi4+/ch5.dynamic.html?utm_source=gemini\">System V ABI: Dynamic Section</a></p>\n<hr />\n","group":"L2","line":621},{"id":"content/06_tools_build_debug/01_build.md:71740c17cf3430b5:1","question":"<p>(L3, T) Разница RPATH vs RUNPATH?</p>\n","answer":"<p><strong>Ответ:</strong> <code>RPATH</code> имеет наивысший приоритет и опрашивается <em>до</em> <code>LD_LIBRARY_PATH</code>. <code>RUNPATH</code> проверяется <em>после</em> <code>LD_LIBRARY_PATH</code>, что дает разработчику возможность переопределять библиотеки окружением.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Порядок поиска:\n1. RPATH (если RUNPATH пуст)\n2. LD_LIBRARY_PATH\n3. RUNPATH\n4. Системный кэш /etc/ld.so.cache\n5. /lib, /usr/lib\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man8/ld.so.8.html?utm_source=gemini\">Linux man-pages: ld.so(8)</a></p>\n","group":"L3","line":637},{"id":"content/06_tools_build_debug/01_build.md:f5169dc7d759c588:1","question":"<p>(L3, T) Что такое symbol interposition?</p>\n","answer":"<p><strong>Ответ:</strong> Механизм, при котором динамический загрузчик разрешает одинаковые символы в пользу того, кто был загружен первым (или через <code>LD_PRELOAD</code>), перехватывая вызовы оригинальных библиотечных функций.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Подмена стандартного аллокатора:\nLD_PRELOAD=/usr/lib/libtcmalloc.so ./my_app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.akkadia.org/drepper/dsohowto.pdf?utm_source=gemini\">Ulrich Drepper: How To Write Shared Libraries</a></p>\n","group":"L3","line":654},{"id":"content/06_tools_build_debug/01_build.md:a56aee4df0e3cb89:1","question":"<p>(L3, D) Почему бинарь использует не ту версию библиотеки?</p>\n","answer":"<p><strong>Ответ:</strong> Из-за порядка поиска: загрузчик нашел устаревшую версию с тем же SONAME в папке из <code>LD_LIBRARY_PATH</code> или системном кэше <code>/etc/ld.so.cache</code> раньше, чем целевую библиотеку из целевой папки.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Трассировка разрешения библиотек:\nLD_DEBUG=libs ./my_app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man8/ld.so.8.html?utm_source=gemini\">Linux man-pages: ld.so(8)</a></p>\n","group":"L3","line":667},{"id":"content/06_tools_build_debug/01_build.md:8c192b7cf130e550:1","question":"<p>(L3, P) Как задать rpath при линковке?</p>\n","answer":"<p><strong>Ответ:</strong> Через ключ компоновщика <code>-Wl,-rpath,ПУТЬ</code>. Часто используется токен <code>$ORIGIN</code> для создания переносимых каталогов (относительно положения бинарника).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">gcc main.c -Wl,-rpath,'$ORIGIN/../lib' -L./lib -lutil -o bin/app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Link-Options.html?utm_source=gemini\">GCC Linker Options</a></p>\n","group":"L3","line":680},{"id":"content/06_tools_build_debug/01_build.md:0c089a1710591f79:1","question":"<p>(L3, T) Как shared libs влияют на startup time?</p>\n","answer":"<p><strong>Ответ:</strong> Замедляют старт программы: динамический загрузчик тратит время на открытие сотен файлов (<code>open</code>/<code>mmap</code>), валидацию ELF, разрешение тысяч символов через хеш-таблицы (<code>.gnu.hash</code>) и правку памяти в GOT/PLT.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Флаг немедленной загрузки замедляет старт, но ускоряет работу:\ngcc -Wl,-z,now main.o -o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.brendangregg.com/methodology.html?utm_source=gemini\">Brendan Gregg: Systems Performance (Startup Latency)</a></p>\n<hr />\n","group":"L3","line":692},{"id":"content/06_tools_build_debug/01_build.md:861cf6e1f04322a4:1","question":"<p>(L4, T) Как реализовать plugin system через <code>.so</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Вызовом POSIX API <code>dlopen</code> с флагом <code>RTLD_NOW|RTLD_LOCAL</code> для изолированной загрузки библиотеки и получением указателей на функции интерфейса через <code>dlsym</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">void* handle = dlopen(&quot;./plugin.so&quot;, RTLD_NOW);\ntypedef void (*PluginFunc)();\nPluginFunc run = (PluginFunc)dlsym(handle, &quot;execute_plugin&quot;);\nrun();\ndlclose(handle);\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://man7.org/linux/man-pages/man3/dlopen.3.html?utm_source=gemini\">Linux man-pages: dlopen(3)</a></p>\n","group":"L4","line":709},{"id":"content/06_tools_build_debug/01_build.md:5c803919e678104c:1","question":"<p>(L4, D) Как диагностировать ABI break между версиями <code>.so</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать инструменты семантического анализа ELF: <code>abi-compliance-checker</code> и <code>abidiff</code>, сравнивающие публичный интерфейс библиотек по типам, смещениям полей структур и сигнатурам.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">abi-compliance-checker -l libfoo -old v1.xml -new v2.xml\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://github.com/lvc/abi-compliance-checker?utm_source=gemini\">ABI Compliance Checker</a></p>\n","group":"L4","line":725},{"id":"content/06_tools_build_debug/01_build.md:7bcc9b0c03a6bce1:1","question":"<p>(L4, S) Когда static linking — единственный вариант?</p>\n","answer":"<p><strong>Ответ:</strong> В initramfs/rescue окружениях ядра; в микро-контейнерах без glibc (<code>scratch</code>/<code>alpine</code> со static musl); в embedded RTOS; в серверах с ультра-жесткими требованиями к startup-latency (где 200 мс на <code>ld.so</code> недопустимы).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Docker FROM scratch\nCOPY my_app /my_app # Работает только при static linking!\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://wiki.alpinelinux.org/wiki/Functional_differences_with_glibc?utm_source=gemini\">Alpine Linux: Functional differences with glibc</a></p>\n<hr />\n","group":"L4","line":737},{"id":"content/06_tools_build_debug/01_build.md:1d33a1f56a826e0d:1","question":"<p>(L1, T) Что такое ABI?</p>\n","answer":"<p><strong>Ответ:</strong> Application Binary Interface — низкоуровневый интерфейс между скомпилированными бинарными модулями: правила передачи аргументов регистрами, размеры и выравнивание типов данных, вызовы системных функций и формат объектных файлов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>System V AMD64 ABI: первые 6 аргументов целочисленных функций передаются через rdi, rsi, rdx, rcx, r8, r9.\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gitlab.com/x86-psABIs/x86-64-ABI?utm_source=gemini\">System V Application Binary Interface (AMD64 Architecture)</a></p>\n","group":"L1","line":756},{"id":"content/06_tools_build_debug/01_build.md:4f5c600427b8aa42:1","question":"<p>(L1, T) Разница ABI vs API?</p>\n","answer":"<p><strong>Ответ:</strong> API определяет совместимость на уровне <em>исходного кода</em> (названия функций, типы аргументов, заголовочные файлы). ABI определяет совместимость на уровне <em>машинного бинарного кода</em> (расположение байт в памяти, соглашения о вызовах, mangling).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Изменили приватное поле в классе:\nAPI не сломался (код компилируется),\nABI сломался (сместились поля в памяти, нужен ребилд клиентов).\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://community.kde.org/Policies/Binary_Compatibility_Issues_With_C%2B%2B?utm_source=gemini\">KDE Community: Binary Compatibility Issues</a></p>\n<hr />\n","group":"L1","line":768},{"id":"content/06_tools_build_debug/01_build.md:fc605c60e06237b7:1","question":"<p>(L2, T) Что входит в ABI?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Набор инструкций процессора; 2) Соглашения о вызовах (calling conventions); 3) Выравнивание и раскладка структур в памяти; 4) Схема декорирования имен (name mangling); 5) Раскладка виртуальных таблиц (<code>vtable</code>); 6) Механизм раскрутки исключений.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">struct Test {\n    char c; // 1 байт + 3 байта паддинга\n    int i;  // 4 байта (выровнено по 4 байтам согласно ABI)\n};\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://itanium-cxx-abi.github.io/cxx-abi/?utm_source=gemini\">Itanium C++ ABI</a></p>\n","group":"L2","line":786},{"id":"content/06_tools_build_debug/01_build.md:feac33f6e45294dd:1","question":"<p>(L2, T) Что такое name mangling?</p>\n","answer":"<p><strong>Ответ:</strong> Шифрование компилятором C++ имени функции, ее пространства имен и типов параметров в одну уникальную строку символов для линкера, необходимое для поддержки перегрузки функций.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cpp\">void foo(int); // Mangled: _Z3fooi\nvoid foo(double); // Mangled: _Z3food\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://itanium-cxx-abi.github.io/cxx-abi/abi.html?utm_source=gemini#mangling\">Itanium C++ ABI: External Names (Mangler)</a></p>\n","group":"L2","line":801},{"id":"content/06_tools_build_debug/01_build.md:f173ec892105e8be:1","question":"<p>(L2, T) Как влияет layout struct на ABI?</p>\n","answer":"<p><strong>Ответ:</strong> Изменение типа, добавление поля или перестановка полей в структуре меняет смещения (offsets) в байтах. Если клиентский код скомпилирован со старыми смещениями, чтение поля попадет в соседние чужие байты (UB и память ломается).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">// Версия 1: struct S { int a; };        -&gt; offset(a) = 0\n// Версия 2: struct S { int x; int a; }; -&gt; offset(a) = 4 (ABI сломан!)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Structure-Layout-Pragmas.html?utm_source=gemini\">GCC Data Alignment and Padding</a></p>\n","group":"L2","line":814},{"id":"content/06_tools_build_debug/01_build.md:392de29febddefc7:1","question":"<p>(L2, D) Почему бинарь ломается после обновления библиотеки?</p>\n","answer":"<p><strong>Ответ:</strong> Нарушена бинарная совместимость (ABI break): библиотека обновилась с новыми размерами структур или измененной таблицей виртуальных функций, но исполняемый файл не был пересобран и работает по старым адресам памяти.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Клиент вызывает vtable[2], а в новой библиотеке этот метод сдвинулся на vtable[3].\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://herbsutter.com/?utm_source=gemini\">Herb Sutter: How To Design a Stable C++ ABI</a></p>\n<hr />\n","group":"L2","line":827},{"id":"content/06_tools_build_debug/01_build.md:c598604b027420d8:1","question":"<p>(L3, T) Что ломает ABI?</p>\n","answer":"<p><strong>Ответ:</strong> Добавление/удаление виртуальных методов; добавление нестатических полей в класс; смена сигнатуры методов; замена типов аргументов; смена компилятора или стандартной библиотеки с другим манглингом; изменение флагов выравнивания (<code>#pragma pack</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cpp\">// Добавление виртуального метода меняет индексы vtable:\nclass Base {\n    virtual void a();\n    virtual void new_method(); // Сломает вызов b() у всех старых клиентов!\n    virtual void b();\n};\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://community.kde.org/Policies/Binary_Compatibility_Issues_With_C%2B%2B?utm_source=gemini\">KDE Policies: Binary Compatibility</a></p>\n","group":"L3","line":843},{"id":"content/06_tools_build_debug/01_build.md:fba5d3101de8cf8c:1","question":"<p>(L3, T) Как vtable влияет на ABI?</p>\n","answer":"<p><strong>Ответ:</strong> Таблица виртуальных методов — это массив указателей на функции. Компилятор хардкодит вызовы методов в виде константных индексов (<code>vtable[N]</code>). Любое смещение порядка методов в классе приводит к вызову не той функции.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>call [rax + 16] // Жестко скомпилированный вызов 3-го виртуального метода\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://itanium-cxx-abi.github.io/cxx-abi/abi.html?utm_source=gemini#vtable\">Itanium C++ ABI: Virtual Table Layout</a></p>\n","group":"L3","line":860},{"id":"content/06_tools_build_debug/01_build.md:48ab10c214b4ba2a:1","question":"<p>(L3, T) Почему inline функции опасны для ABI?</p>\n","answer":"<p><strong>Ответ:</strong> Тело <code>inline</code> функции копируется непосредственно в код вызывающей программы во время ее компиляции. Если внутренняя логика функции в библиотеке изменится, старые программы продолжат выполнять заинлайненный старый код, создавая рассогласование состояний.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cpp\">// my_lib.h\ninline int get_timeout() { return 1000; } // Вшивается клиентам навечно\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.aristeia.com/books.html?utm_source=gemini\">Effective C++ (Scott Meyers)</a></p>\n","group":"L3","line":872},{"id":"content/06_tools_build_debug/01_build.md:11300811dbbed921:1","question":"<p>(L3, D) Как обнаружить ABI mismatch?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Запустить <code>pahole</code> на двух версиях библиотек и сопоставить байтовые смещения членов структур; 2) Использовать <code>abidiff</code> из пакета libabigail для генерации отчета об изменениях типов и символов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">pahole -C MyStruct libv1.so\npahole -C MyStruct libv2.so\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://git.kernel.org/pub/scm/devel/pahole/pahole.git/?utm_source=gemini\">Pahole (Poke-a-hole) tool</a></p>\n<hr />\n","group":"L3","line":885},{"id":"content/06_tools_build_debug/01_build.md:73d1c1c9f74185c7:1","question":"<p>(L4, S) Как проектировать стабильный ABI?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Использовать pImpl-идиому (Pointer to Implementation) для сокрытия полей классов; 2) Экспортировать только чистый C-интерфейс (<code>extern &quot;C&quot;</code>); 3) Никогда не удалять и не менять порядок виртуальных методов; 4) Резервировать паддинг в структурах под будущие поля.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cpp\">class StableApi {\n    struct Impl;\n    Impl* pimpl; // Размер указателя неизменен (8 байт), любые изменения скрыты в .cpp\n};\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://herbsutter.com/gotw/_100/?utm_source=gemini\">Herb Sutter: Pimpl Idiom</a></p>\n","group":"L4","line":902},{"id":"content/06_tools_build_debug/01_build.md:2a5c28f40fd3fbdc:1","question":"<p>(L4, S) Как поддерживать backward compatibility?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать Symbol Versioning в ELF (директивы <code>.symver</code> в ассемблере), позволяя экспортировать одновременно старую и новую версии одной и той же функции под разными версионными метками.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">__asm__(&quot;.symver old_foo, foo@LIB_1.0&quot;);\n__asm__(&quot;.symver new_foo, foo@@LIB_2.0&quot;);\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://sourceware.org/binutils/docs/ld/VERSION.html?utm_source=gemini\">GNU ld: Symbol Versioning</a></p>\n<hr />\n","group":"L4","line":917},{"id":"content/06_tools_build_debug/01_build.md:75dd3032c9daf17c:1","question":"<p>(L1, T) Что такое Makefile?</p>\n","answer":"<p><strong>Ответ:</strong> Конфигурационный файл для утилиты <code>make</code>, содержащий декларативный набор правил: целевые файлы, их зависимости и скриптовые команды (рецепты) для их генерации.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">app: main.o\n\tgcc main.o -o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/?utm_source=gemini\">GNU Make Manual</a></p>\n","group":"L1","line":936},{"id":"content/06_tools_build_debug/01_build.md:d8059228ac39d754:1","question":"<p>(L1, T) Что такое target?</p>\n","answer":"<p><strong>Ответ:</strong> Цель (target) — имя сущности в правиле Makefile (обычно имя генерируемого файла бинарника/библиотеки) или псевдо-действие (clean, all), которое необходимо выполнить.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">clean: # target\n\trm -f *.o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Rule-Syntax.html?utm_source=gemini\">GNU Make: Rule Syntax</a></p>\n","group":"L1","line":949},{"id":"content/06_tools_build_debug/01_build.md:974f9b0d2b94b145:1","question":"<p>(L1, T) Что такое dependency?</p>\n","answer":"<p><strong>Ответ:</strong> Файл (или другая цель), от которого зависит целевой файл. Если время изменения зависимости новее времени изменения цели, Make выполняет рецепт.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">app: main.o utils.o # dependencies\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Prerequisite-Types.html?utm_source=gemini\">GNU Make: Prerequisites</a></p>\n","group":"L1","line":962},{"id":"content/06_tools_build_debug/01_build.md:811b3468aaa14a0a:1","question":"<p>(L1, P) Написать простой Makefile</p>\n","answer":"<p><strong>Ответ:</strong> Минимальный Makefile с компиляцией и линковкой.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">CC = gcc\nCFLAGS = -Wall -O2\n\napp: main.o\n\t$(CC) main.o -o app\n\nmain.o: main.c\n\t$(CC) $(CFLAGS) -c main.c -o main.o\n\nclean:\n\trm -f *.o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Simple-Makefile.html?utm_source=gemini\">GNU Make: Simple Makefile</a></p>\n<hr />\n","group":"L1","line":974},{"id":"content/06_tools_build_debug/01_build.md:129dd06887ddb41a:1","question":"<p>(L2, T) Как Make решает, что пересобирать?</p>\n","answer":"<p><strong>Ответ:</strong> Make сравнивает метку времени последнего изменения файла цели (<code>mtime</code>) с метками времени всех его зависимостей. Если хотя бы одна зависимость имеет более свежий <code>mtime</code> или цель отсутствует на диске — правило запускается.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>main.c (12:05) &gt; main.o (12:00) -&gt; Нужен ребилд main.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/How-Make-Works.html?utm_source=gemini\">GNU Make: How Make Works</a></p>\n","group":"L2","line":1000},{"id":"content/06_tools_build_debug/01_build.md:d7f2d679ea48fe47:1","question":"<p>(L2, T) Что такое <code>.PHONY</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Специальная служебная цель, указывающая Make, что цель не является физическим файлом на диске. Это предотвращает коллизии, если в папке появится реальный файл с именем цели (например, файл <code>clean</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">.PHONY: all clean test\nclean:\n\trm -f *.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Phony-Targets.html?utm_source=gemini\">GNU Make: Phony Targets</a></p>\n","group":"L2","line":1012},{"id":"content/06_tools_build_debug/01_build.md:2b09c3f698c252e4:1","question":"<p>(L2, P) Использование <code>$@</code>, <code>$&lt;</code>, <code>$^</code></p>\n","answer":"<p><strong>Ответ:</strong> Автоматические переменные Make:</p>\n","group":"L2","line":1026},{"id":"content/06_tools_build_debug/01_build.md:b8e9900629334515:1","question":"<p>(L2, P) Pattern rules</p>\n","answer":"<p><strong>Ответ:</strong> Шаблонные правила с символом <code>%</code> для компактного описания компиляции классов файлов (например, как из любого <code>.c</code> получить <code>.o</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">%.o: %.c\n\t$(CC) $(CFLAGS) -c $&lt; -o $@\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Pattern-Rules.html?utm_source=gemini\">GNU Make: Pattern Rules</a></p>\n","group":"L2","line":1048},{"id":"content/06_tools_build_debug/01_build.md:11551934b7d0836f:1","question":"<p>(L2, D) Почему пересобирается всё?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Файл цели не генерируется рецептом (Make ищет его снова и снова); 2) Часы системы сбиты (файл из будущего); 3) В зависимостях указана Phony-цель; 4) Makefile сам зависит от файла, который постоянно меняется.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Диагностика причин пересборки в Make:\nmake --debug=why\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Options-Summary.html?utm_source=gemini\">GNU Make: Debugging</a></p>\n<hr />\n","group":"L2","line":1061},{"id":"content/06_tools_build_debug/01_build.md:02741c9c09079e39:1","question":"<p>(L3, T) Как работают dependency files (.d)?</p>\n","answer":"<p><strong>Ответ:</strong> Файлы <code>.d</code> содержат списки всех заголовочных файлов, включенных в конкретный <code>.c</code>. Make динамически импортирует их через <code>include</code>, чтобы пересобирать <code>.o</code> файл при изменении любого вложенного хедера.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">-include $(OBJS:.o=.d)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Automatic-Prerequisites.html?utm_source=gemini\">GNU Make: Auto-Dependencies</a></p>\n","group":"L3","line":1078},{"id":"content/06_tools_build_debug/01_build.md:801c6b7fd5fc94a6:1","question":"<p>(L3, P) Генерация зависимостей через <code>-MMD</code></p>\n","answer":"<p><strong>Ответ:</strong> Флаги <code>-MMD -MP</code> заставляют компилятор параллельно с компиляцией генерировать валидный фрагмент Makefile со списком пользовательских хедеров.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">CFLAGS += -MMD -MP\n\n-include $(wildcard *.d)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Preprocessor-Options.html?utm_source=gemini#index-MMD\">GCC Preprocessor Options (-MMD)</a></p>\n","group":"L3","line":1090},{"id":"content/06_tools_build_debug/01_build.md:df903ce7d67e435f:1","question":"<p>(L3, D) Как избежать stale headers?</p>\n","answer":"<p><strong>Ответ:</strong> Флаг <code>-MP</code> генерирует фиктивные пустые правила для каждого заголовка. Это предотвращает падение Make с ошибкой <code>No rule to make target 'old.h'</code>, если старый заголовок был удален с диска.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\"># Сгенерированный .d файл содержит:\nold.h:\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Preprocessor-Options.html?utm_source=gemini#index-MP\">GCC Options: -MP</a></p>\n","group":"L3","line":1104},{"id":"content/06_tools_build_debug/01_build.md:5e38d2e998e2ca8a:1","question":"<p>(L3, T) Почему recursive make плох?</p>\n","answer":"<p><strong>Ответ:</strong> Рекурсивный вызов <code>$(MAKE) -C subdir</code> изолирует графы зависимостей разных подпапок. Make теряет глобальный контекст проекта, что ломает корректную параллелизацию (<code>-j</code>), приводит к ложным пересборкам и ошибкам порядка линковки.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Recursive Make Considered Harmful (Peter Miller, 1997)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://aegis.sourceforge.net/auug97.pdf?utm_source=gemini\">Miller, P.: Recursive Make Considered Harmful</a></p>\n<hr />\n","group":"L3","line":1117},{"id":"content/06_tools_build_debug/01_build.md:273e78c7cccc39b6:1","question":"<p>(L4, S) Как масштабировать Make на большой проект?</p>\n","answer":"<p><strong>Ответ:</strong> Перейти на Non-Recursive Make (единый монолитный граф зависимостей проекта через подключение множества фрагментов <code>include module.mk</code>), либо использовать Make исключительно как тонкую обертку над метагенератором сборочных файлов Ninja.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">include src/net/rules.mk\ninclude src/db/rules.mk\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"http://evbergen.home.xs4all.nl/nonrecursive-make.html?utm_source=gemini\">Emile van Bergen: Non-recursive Make Made Easy</a></p>\n","group":"L4","line":1133},{"id":"content/06_tools_build_debug/01_build.md:70ccfb5d3dedd046:1","question":"<p>(L4, D) Почему build не детерминирован с <code>-j</code>?</p>\n","answer":"<p><strong>Ответ:</strong> Отсутствуют явные зависимости между целями (race condition в сборке). Поток A пытается слинковать бинарник, пока поток B еще компилирует нужный для него <code>.o</code> файл. При сборке в 1 поток порядок случайно соблюдался.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\"># Баг: app зависит от lib.a, но зависимость не объявлена:\napp: main.o\n\tgcc main.o -L. -llib -o app\n# С -j8 упадет, если lib.a еще не готов!\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.gnu.org/software/make/manual/html_node/Parallel.html?utm_source=gemini\">GNU Make: Parallel Execution</a></p>\n<hr />\n","group":"L4","line":1146},{"id":"content/06_tools_build_debug/01_build.md:810229fac96a8adf:1","question":"<p>(L1, T) Что такое CMake?</p>\n","answer":"<p><strong>Ответ:</strong> Кроссплатформенный метагенератор систем сборки: он считывает файлы <code>CMakeLists.txt</code> и генерирует нативные скрипты сборки под платформу (Makefile, Ninja, Visual Studio, Xcode).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">cmake -B build -G Ninja\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/documentation/?utm_source=gemini\">CMake Official Documentation</a></p>\n","group":"L1","line":1167},{"id":"content/06_tools_build_debug/01_build.md:99f53885a157b82c:1","question":"<p>(L1, T) Что такое out-of-source build?</p>\n","answer":"<p><strong>Ответ:</strong> Практика разделения исходников и артефактов компиляции, при которой сгенерированные объектные файлы, кэш CMake и бинарники складываются в отдельную изолированную папку (например, <code>build/</code>), не засоряя дерево репозитория.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">cmake -B build -S .\ncmake --build build\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gitlab.kitware.com/cmake/community/-/wikis/FAQ#what-is-an-out-of-source-build?utm_source=gemini\">CMake Out-of-Source Guide</a></p>\n","group":"L1","line":1179},{"id":"content/06_tools_build_debug/01_build.md:bd6b727b16b653d6:1","question":"<p>(L1, P) Минимальный CMakeLists.txt</p>\n","answer":"<p><strong>Ответ:</strong> Минимальный манифест для сборки приложения.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">cmake_minimum_required(VERSION 3.20)\nproject(App LANGUAGES CXX)\n\nadd_executable(my_app main.cpp)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/guide/tutorial/index.html?utm_source=gemini\">CMake Tutorial</a></p>\n<hr />\n","group":"L1","line":1192},{"id":"content/06_tools_build_debug/01_build.md:1a4eb6136e3334ca:1","question":"<p>(L2, T) Что такое target?</p>\n","answer":"<p><strong>Ответ:</strong> Основной строительный блок в современном CMake, представляющий артефакт сборки (исполняемый файл или библиотеку), к которому инкапсулированно привязываются исходники, пути заголовков, флаги и зависимости.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">add_library(Engine STATIC engine.cpp)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/manual/cmake-buildsystem.7.html?utm_source=gemini#targets\">CMake Targets</a></p>\n","group":"L2","line":1211},{"id":"content/06_tools_build_debug/01_build.md:3d1e0d2c00f56098:1","question":"<p>(L2, T) PUBLIC vs PRIVATE vs INTERFACE</p>\n","answer":"<p><strong>Ответ:</strong> Спецификаторы транзитивности зависимостей target:</p>\n","group":"L2","line":1223},{"id":"content/06_tools_build_debug/01_build.md:cd69a701c9886fda:1","question":"<p>(L2, P) add_executable / add_library</p>\n","answer":"<p><strong>Ответ:</strong> Команды создания целей исполнения и библиотек (<code>STATIC</code>, <code>SHARED</code>, <code>INTERFACE</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">add_library(Core STATIC core.cpp)\nadd_executable(App main.cpp)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/manual/cmake-commands.7.html?utm_source=gemini\">CMake Command Reference</a></p>\n","group":"L2","line":1241},{"id":"content/06_tools_build_debug/01_build.md:2b2875ee20f281e9:1","question":"<p>(L2, P) target_link_libraries</p>\n","answer":"<p><strong>Ответ:</strong> Связывает зависимости между целями, автоматически пробрасывая флаги линковщика, пути поиска инклудов и дефайны компилятора согласно их транзитивности.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">target_link_libraries(App PRIVATE Core)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/command/target_link_libraries.html?utm_source=gemini\">CMake: target_link_libraries</a></p>\n<hr />\n","group":"L2","line":1254},{"id":"content/06_tools_build_debug/01_build.md:8a84c724a23d2798:1","question":"<p>(L3, T) Как работает find_package?</p>\n","answer":"<p><strong>Ответ:</strong> Команда ищет внешнюю библиотеку в системе. Работает в двух режимах: ищет файл поиска <code>Find&lt;Package&gt;.cmake</code> в путях <code>CMAKE_MODULE_PATH</code>, либо ищет готовый конфигурационный пакет <code>&lt;Package&gt;Config.cmake</code>, поставляемый самой библиотекой.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">find_package(OpenSSL REQUIRED)\ntarget_link_libraries(App PRIVATE OpenSSL::SSL)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/command/find_package.html?utm_source=gemini\">CMake: find_package</a></p>\n","group":"L3","line":1270},{"id":"content/06_tools_build_debug/01_build.md:90988ffd4587ef9c:1","question":"<p>(L3, T) Module vs Config mode</p>\n","answer":"<p><strong>Ответ:</strong> Module mode ищет внешний скрипт-обертку <code>FindXXX.cmake</code> (пишется третьими лицами или CMake). Config mode ищет файл <code>XXXConfig.cmake</code>, который сгенерирован и установлен автором самой библиотеки с точным описанием ее таргетов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">find_package(Boost CONFIG REQUIRED) # Принудительно Config mode\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/command/find_package.html?utm_source=gemini#search-modes\">CMake Packages Modes</a></p>\n","group":"L3","line":1283},{"id":"content/06_tools_build_debug/01_build.md:b35647def0493487:1","question":"<p>(L3, P) Использование toolchain file</p>\n","answer":"<p><strong>Ответ:</strong> Файл скрипта, передаваемый параметром <code>-DCMAKE_TOOLCHAIN_FILE</code>, переопределяющий целевую платформу, системный корень (sysroot) и пути к кросс-компиляторам.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\"># arm-toolchain.cmake\nset(CMAKE_SYSTEM_NAME Linux)\nset(CMAKE_SYSTEM_PROCESSOR arm)\nset(CMAKE_C_COMPILER arm-linux-gnueabihf-gcc)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/manual/cmake-toolchains.7.html?utm_source=gemini\">CMake Toolchains</a></p>\n","group":"L3","line":1295},{"id":"content/06_tools_build_debug/01_build.md:15f0652bcd9ee401:1","question":"<p>(L3, D) Почему не находится библиотека?</p>\n","answer":"<p><strong>Ответ:</strong> Каталог установки библиотеки отсутствует в путях поиска <code>CMAKE_PREFIX_PATH</code>; не совпадает регистр букв в имени; библиотека собрана под другую разрядность (32 vs 64 бит); отсутствуют права доступа к директории.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">cmake -B build -DCMAKE_PREFIX_PATH=/opt/my_custom_package\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/variable/CMAKE_PREFIX_PATH.html?utm_source=gemini\">CMake: CMAKE_PREFIX_PATH</a></p>\n<hr />\n","group":"L3","line":1310},{"id":"content/06_tools_build_debug/01_build.md:45bbf770c6e1f853:1","question":"<p>(L4, S) Как проектировать CMake для large-scale проекта?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Строго следовать парадигме Modern Target-based CMake (никаких глобальных <code>include_directories</code>); 2) Использовать алиасы таргетов (<code>MyLib::Core</code>); 3) Ограничивать видимость через <code>PRIVATE</code>; 4) Разделять проект на независимые компоненты, поддерживающие установку (<code>install(EXPORT)</code>); 5) Использовать <code>ccache</code> и PCH.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">add_library(MyOrg::Core ALIAS Core)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://crascit.com/professional-cmake/?utm_source=gemini\">Professional CMake: A Practical Guide (Craig Scott)</a></p>\n","group":"L4","line":1326},{"id":"content/06_tools_build_debug/01_build.md:8726849d5453b5ec:1","question":"<p>(L4, T) Как реализовать reusable modules?</p>\n","answer":"<p><strong>Ответ:</strong> Написать <code>*Config.cmake.in</code> шаблон с использованием генератора экспорта таргетов <code>CMakePackageConfigHelpers</code>, формируя экспортируемый namespace при установке.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cmake\">install(TARGETS Core EXPORT CoreTargets DESTINATION lib)\ninstall(EXPORT CoreTargets NAMESPACE MyLib:: DESTINATION lib/cmake/MyLib)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/manual/cmake-packages.7.html?utm_source=gemini\">CMake: Packaging Software</a></p>\n","group":"L4","line":1338},{"id":"content/06_tools_build_debug/01_build.md:b83683b141da721c:1","question":"<p>(L4, D) Debugging сложного dependency graph</p>\n","answer":"<p><strong>Ответ:</strong> Сгенерировать граф зависимостей в формате Graphviz с помощью флага <code>--graphviz</code> и визуализировать его утилитой <code>dot</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">cmake -B build --graphviz=graph.dot\ndot -Tpng graph.dot -o deps.png\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/module/CMakeGraphVizOptions.html?utm_source=gemini\">CMake Graphviz Support</a></p>\n<hr />\n","group":"L4","line":1351},{"id":"content/06_tools_build_debug/01_build.md:e61b0a9721d5cabd:1","question":"<p>(L2, T) Почему Ninja быстрее Make?</p>\n","answer":"<p><strong>Ответ:</strong> Ninja предельно упрощена: в ней нет циклов, скриптовых условий и функций. Входной файл <code>build.ninja</code> содержит плоский готовый граф. Ninja загружает его за миллисекунды, мгновенно опрашивает mtime через системные батч-вызовы и полностью параллелит сборку без блокировок.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">ninja -C build -j 16\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://ninja-build.org/?utm_source=gemini\">The Ninja Build System</a></p>\n","group":"L2","line":1370},{"id":"content/06_tools_build_debug/01_build.md:c729517e65df568b:1","question":"<p>(L2, T) Что такое minimal build system?</p>\n","answer":"<p><strong>Ответ:</strong> Сборочный инструмент (типа Ninja), намеренно лишенный высокоуровневой логики конфигурирования. Его единственная задача — максимально быстро исполнить готовый ориентированный граф команд без вычислений условий на лету.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>CMake (High-Level Meta) -&gt; генерирует build.ninja -&gt; Ninja (Minimal Low-Level Engine)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://ninja-build.org/manual.html?utm_source=gemini#_design_goals\">Ninja Design Principles</a></p>\n<hr />\n","group":"L2","line":1382},{"id":"content/06_tools_build_debug/01_build.md:c1d64fb7bcabe48e:1","question":"<p>(L3, T) Что такое hermetic build (Bazel)?</p>\n","answer":"<p><strong>Ответ:</strong> Герметичная сборка — система, в которой сборка изолирована от хостовой машины: используются строго фиксированные тулчейны, скачиваемые самой системой сборки, а доступ к глобальным <code>/usr/include</code> и сети во время компиляции заблокирован.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-python\"># WORKSPACE: фиксация компилятора и зависимостей вплоть до sha256\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://bazel.build/basics/hermeticity?utm_source=gemini\">Bazel: Hermeticity</a></p>\n","group":"L3","line":1398},{"id":"content/06_tools_build_debug/01_build.md:24febe528ae41031:1","question":"<p>(L3, T) Что такое sandboxing?</p>\n","answer":"<p><strong>Ответ:</strong> Запуск каждого шага компиляции в изолированном пространстве (Linux namespaces / chroot): шаг сборки видит строго те входные файлы, которые были явно объявлены в зависимостях. Если забыли объявить инклуд — сборка упадет.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Bazel выполняет компиляцию в пустой песочнице с симлинками только на разрешенные файлы.\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://bazel.build/docs/sandboxing?utm_source=gemini\">Bazel Sandboxing</a></p>\n","group":"L3","line":1410},{"id":"content/06_tools_build_debug/01_build.md:733e4491f3edd295:1","question":"<p>(L3, T) Что такое reproducible build?</p>\n","answer":"<p><strong>Ответ:</strong> Сборка, гарантирующая идентичность итоговых бинарных файлов байт-в-байт при сборке из одного и того же коммита на любой машине в любое время (исключены влияние временных меток, путей и порядка файлов).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">sha256sum build_a/app build_b/app # Хэши совпадают на 100%\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://reproducible-builds.org/?utm_source=gemini\">Reproducible Builds Project</a></p>\n<hr />\n","group":"L3","line":1422},{"id":"content/06_tools_build_debug/01_build.md:79a8c11a2446b209:1","question":"<p>(L4, S) Когда стоит мигрировать на Bazel?</p>\n","answer":"<p><strong>Ответ:</strong> Когда размер монорепозитория превышает миллионы строк кода, кодовая база мультиязычна (C++, Java, Go, Python), сборка на одной машине занимает часы, и критически необходим распределенный кэш (Remote Caching) и распределенное выполнение (Remote Execution).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Google, Uber, Stripe используют Bazel для монорепозиториев.\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://bazel.build/faq?utm_source=gemini\">Bazel FAQ: When should I use Bazel?</a></p>\n","group":"L4","line":1438},{"id":"content/06_tools_build_debug/01_build.md:254d9255a50f958d:1","question":"<p>(L4, S) Trade-offs Meson vs CMake</p>\n","answer":"<p><strong>Ответ:</strong> Meson проще, имеет строгий непрограммируемый синтаксис (меньше спагетти-кода), работает поверх Ninja по умолчанию и очень быстр. CMake сложнее, имеет синтаксис на макросах, но является абсолютным стандартом индустрии с поддержкой любых IDE, библиотек и тулчейнов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Meson идеален для GNOME/Systemd проектов чистого C.\nCMake обязателен для коммерческого C++ из-за интеграций.\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://mesonbuild.com/Comparisons.html?utm_source=gemini\">Meson Build System vs CMake Comparison</a></p>\n<hr />\n","group":"L4","line":1450},{"id":"content/06_tools_build_debug/01_build.md:974f9b0d2b94b145:2","question":"<p>(L1, T) Что такое dependency?</p>\n","answer":"<p><strong>Ответ:</strong> Сторонняя библиотека, модуль или компонент, функции которого вызываются программой для реализации требуемой функциональности без написания собственного аналога.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Наш сервис -&gt; зависит от libcurl -&gt; зависит от OpenSSL\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://abseil.io/resources/swe-book?utm_source=gemini\">Software Engineering at Google (Titus Winters)</a></p>\n","group":"L1","line":1469},{"id":"content/06_tools_build_debug/01_build.md:783ef697b1359aff:1","question":"<p>(L1, T) Что такое system package?</p>\n","answer":"<p><strong>Ответ:</strong> Библиотека или инструмент, установленный централизованно администратором в глобальные каталоги операционной системы через пакетный менеджер дистрибутива (<code>apt</code>, <code>yum</code>, <code>pacman</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">sudo apt install libboost-all-dev\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.debian.org/doc/manuals/debian-faq/pkg-basics.en.html?utm_source=gemini\">Debian Package Management Basics</a></p>\n<hr />\n","group":"L1","line":1481},{"id":"content/06_tools_build_debug/01_build.md:0e2ceb53533bcf2a:1","question":"<p>(L2, T) Что такое vendoring?</p>\n","answer":"<p><strong>Ответ:</strong> Практика сохранения исходного кода сторонних библиотек непосредственно внутри своего репозитория (в каталоге <code>third_party/</code> или <code>vendor/</code>), исключающая зависимость процесса сборки от сети и сторонних серверов.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>my_project/\n  ├── src/\n  └── third_party/sqlite/sqlite3.c\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://go.dev/ref/mod#vendoring?utm_source=gemini\">Go Modules and Vendoring Guide</a></p>\n","group":"L2","line":1497},{"id":"content/06_tools_build_debug/01_build.md:d9bcf042cbf03ae2:1","question":"<p>(L2, T) Что такое version pinning?</p>\n","answer":"<p><strong>Ответ:</strong> Явная фиксация точной версии зависимости (вплоть до конкретного тега, коммита или sha256 хеша), запрещающая сборщику подтягивать плавающие новые обновления (типа <code>latest</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>conanfile.txt:\n[requires]\nzlib/1.2.13#b79f88d6b8ef3f48a478b0a94cb22c54\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://docs.conan.io/2/tutorial/consuming_packages.html?utm_source=gemini\">Conan Package Manager: Versioning</a></p>\n","group":"L2","line":1511},{"id":"content/06_tools_build_debug/01_build.md:7268682c92d78bce:1","question":"<p>(L2, D) Почему разные версии ломают билд?</p>\n","answer":"<p><strong>Ответ:</strong> Новая версия может удалить объявленный метод (API break), изменить сигнатуру, или нарушить раскладку байт структур в памяти при линковке со старыми объектниками (ABI break).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-c\">// Было: void init(int);\n// Стало: void init(int, bool); -&gt; Ошибка компиляции: too few arguments\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://semver.org/?utm_source=gemini\">Semantic Versioning 2.0.0</a></p>\n<hr />\n","group":"L2","line":1525},{"id":"content/06_tools_build_debug/01_build.md:54e5d63448f80ed5:1","question":"<p>(L3, T) Что такое dependency hell?</p>\n","answer":"<p><strong>Ответ:</strong> Конфликт транзитивных зависимостей: модуль A требует библиотеку C v1.0, а модуль B требует ту же библиотеку C v2.0. В одном C++ бинарнике нельзя слинковать две разные версии одной библиотеки из-за коллизии глобальных символов (ODR violation).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>       [ App ]\n      /       \\\n  [ LibA ]   [ LibB ]\n     |          |\n  [ C v1 ]   [ C v2 ] -&gt; ODR Crash / Duplicate symbols\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://docs.conan.io/2/knowledge/guidelines.html?utm_source=gemini\">Modern C++ and Package Managers (Conan Docs)</a></p>\n","group":"L3","line":1542},{"id":"content/06_tools_build_debug/01_build.md:b123681c88f5b027:1","question":"<p>(L3, T) Как работает pkg-config?</p>\n","answer":"<p><strong>Ответ:</strong> Утилита считывает специальные манифесты <code>.pc</code>, в которых разработчики библиотек декларируют пути инклудов, флаги линковки и список транзитивных зависимостей, подставляя их в команды компилятора.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">pkg-config --cflags --libs libpng\n# -I/usr/include/libpng16 -lpng16\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.freedesktop.org/wiki/Software/pkg-config/?utm_source=gemini\">Freedesktop: pkg-config Guide</a></p>\n","group":"L3","line":1558},{"id":"content/06_tools_build_debug/01_build.md:48b03793b30c18d5:1","question":"<p>(L3, P) Использование pkg-config</p>\n","answer":"<p><strong>Ответ:</strong> Вызов <code>pkg-config</code> внутри Makefile или интеграция с CMake через <code>PkgConfig</code>.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-makefile\">CFLAGS += $(shell pkg-config --cflags glib-2.0)\nLDFLAGS += $(shell pkg-config --libs glib-2.0)\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://cmake.org/cmake/help/latest/module/FindPkgConfig.html?utm_source=gemini\">CMake: FindPkgConfig</a></p>\n<hr />\n","group":"L3","line":1571},{"id":"content/06_tools_build_debug/01_build.md:4a21391d4f4a6efc:1","question":"<p>(L4, S) Как обеспечить reproducible dependencies?</p>\n","answer":"<p><strong>Ответ:</strong> Использовать пакетные менеджеры с lock-файлами (Conan, vcpkg) с обязательной проверкой криптографических контрольных сумм тарболов; поднимать собственный локальный репозиторий артефактов (Artifactory/Nexus); собирать зависимости в единых герметичных Docker-образах тулчейна.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-json\">// conan.lock фиксирует точный sha256 и все транзитивные узлы графа\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://docs.conan.io/2/knowledge/design_requirements/lockfiles.html?utm_source=gemini\">Conan Lockfiles Architecture</a></p>\n","group":"L4","line":1588},{"id":"content/06_tools_build_debug/01_build.md:100d25b592ecd5fc:1","question":"<p>(L4, S) Как управлять ABI compatibility?</p>\n","answer":"<p><strong>Ответ:</strong> Внедрить автоматический CI-пайплайн проверки ABI (libabigail), блокирующий PR при несовместимости; строго следовать Semantic Versioning; инкапсулировать изменения через Pimpl; избегать передачи STL-контейнеров через границы shared-библиотек.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-yaml\"># CI шаг:\n- name: ABI check\n  run: abidiff --leaf-changes-only old_lib.so new_lib.so\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://developers.redhat.com/blog/2019/04/24/how-to-use-libabigail-to-check-for-abi-changes?utm_source=gemini\">Libabigail in CI (Red Hat Developer)</a></p>\n<hr />\n","group":"L4","line":1600},{"id":"content/06_tools_build_debug/01_build.md:bab688f7eb914c63:1","question":"<p>(L2, D) Билд работает локально, но падает в CI — причины?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Разница в версиях компиляторов и стандартных библиотек; 2) Необъявленная зависимость установлена на локальной машине, но отсутствует в чистом CI контейнере; 3) Чувствительность к регистру файловой системы (macOS case-insensitive vs Linux case-sensitive); 4) Полагание на локальный кэш сборки.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-cpp\">#include &quot;Header.h&quot; // На macOS локально скомпилируется, на Linux в CI упадет: &quot;header.h: No such file&quot;\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://martinfowler.com/articles/continuousIntegration.html?utm_source=gemini\">Martin Fowler: Continuous Integration Pitfalls</a></p>\n","group":"L2","line":1620},{"id":"content/06_tools_build_debug/01_build.md:2718ead66093b3a1:1","question":"<p>(L2, D) Почему не линкуется библиотека?</p>\n","answer":"<p><strong>Ответ:</strong> Ошибочный путь в <code>-L</code>; не указано имя в <code>-l</code>; имя файла не начинается с префикса <code>lib</code> (например, <code>foo.so</code> вместо <code>libfoo.so</code>); несовпадение разрядности архитектуры (x86 vs x86_64).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># /usr/bin/ld: cannot find -lfoo: No such file or directory\n# Решение: добавить путь: -L/path/to/dir\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://gcc.gnu.org/onlinedocs/gcc/Link-Options.html?utm_source=gemini\">GCC Linking Options</a></p>\n<hr />\n","group":"L2","line":1632},{"id":"content/06_tools_build_debug/01_build.md:06c3b3d3f3126561:1","question":"<p>(L3, D) Почему бинарь падает только на другой машине?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Использовался флаг <code>-march=native</code>, сгенерировавший инструкции AVX2/AVX-512, отсутствующие на целевом CPU (падение с <code>Illegal instruction</code>); 2) Бинарник скомпилирован с более новой glibc, чем установлена на целевой ОС (<code>version GLIBC_2.34 not found</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Crash: Illegal instruction (core dumped)\n# Причина: сборка с -march=native запущена на старом процессоре\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://developers.redhat.com/blog/2016/02/23/why-the-new-glibc-breaks-compatibility?utm_source=gemini\">Red Hat: How glibc works and backward compatibility</a></p>\n","group":"L3","line":1649},{"id":"content/06_tools_build_debug/01_build.md:d7cf16edd13368cf:1","question":"<p>(L3, D) Почему изменение header пересобирает весь проект?</p>\n","answer":"<p><strong>Ответ:</strong> Заголовок транзитивно включен в базовый корневой хедер проекта (например, в <code>common.h</code> или <code>pch.h</code>), от которого прямо или косвенно зависят абсолютно все остальные единицы трансляции в графе зависимостей.</p>\n<p><strong>Пример:</strong></p>\n<pre><code>Core.h (изменен) -&gt; включен в Base.h -&gt; включен во все 500 .cpp файлов\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://www.informit.com/store/large-scale-c-plus-plus-software-design-9780201633627?utm_source=gemini\">Large-Scale C++ Software Design (John Lakos)</a></p>\n","group":"L3","line":1662},{"id":"content/06_tools_build_debug/01_build.md:1be256eb3935f14a:1","question":"<p>(L3, D) Почему увеличилось время сборки?</p>\n","answer":"<p><strong>Ответ:</strong> Попадание тяжелых шаблонных заголовочных файлов (STL, Boost, JSON) в часто включаемые хедеры; отключение или инвалидация Precompiled Headers (PCH); раздувание макросов; отключение инкрементальности в CI.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Анализ времени сборки каждого хедера в Clang:\nclang++ -ftime-trace main.cpp\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://aras-p.info/blog/2019/01/16/time-trace-timeline-flame-chart-profiler-for-Clang/?utm_source=gemini\">Aras Pranckevičius: Tune Compilation Times with -ftime-trace</a></p>\n<hr />\n","group":"L3","line":1674},{"id":"content/06_tools_build_debug/01_build.md:ae906c0df2dfe518:1","question":"<p>(L4, S) Как уменьшить build time в 10x?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Заменить линкер <code>ld</code> на многопоточный <code>mold</code> или <code>lld</code> (ускоряет линковку в 5–10 раз); 2) Внедрить распределенный кэш сборки <code>sccache</code> / <code>ccache</code>; 3) Использовать Ninja вместо Make; 4) Внедрить Unity-билды для релизной сборки; 5) Использовать PCH и переходить на C++20 Modules; 6) Сократить инклуды через forward declarations и pImpl.</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\"># Использование mold ускоряет линковку гигантских бинарников с минут до секунд:\nclang++ -fuse-ld=mold main.o -o app\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://github.com/rui314/mold?utm_source=gemini\">Rui Ueyama: Mold - A Modern Linker</a></p>\n","group":"L4","line":1691},{"id":"content/06_tools_build_debug/01_build.md:e419bf14fb898686:1","question":"<p>(L4, S) Как сделать build reproducible?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Зафиксировать все пути компилятора через флаг <code>-ffile-prefix-map</code>; 2) Переопределить макросы времени и даты переменной <code>SOURCE_DATE_EPOCH</code>; 3) Зафиксировать порядок передачи файлов линкеру (сортировка аргументов); 4) Собирать внутри изолированных контейнеров с единым locale (<code>LC_ALL=C</code>).</p>\n<p><strong>Пример:</strong></p>\n<pre><code class=\"language-bash\">export SOURCE_DATE_EPOCH=$(git log -1 --pretty=%ct)\ngcc -ffile-prefix-map=$(pwd)=. -c main.c -o main.o\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://reproducible-builds.org/docs/source-date-epoch/?utm_source=gemini\">Reproducible Builds: SOURCE_DATE_EPOCH Specification</a></p>\n","group":"L4","line":1704},{"id":"content/06_tools_build_debug/01_build.md:9a006b65d8bcc067:1","question":"<p>(L4, S) Как проектировать build system для монорепозитория?</p>\n","answer":"<p><strong>Ответ:</strong> 1) Использовать артефактно-ориентированную систему сборки (Bazel/Buck2) с графом строго ориентированного ациклического вида (DAG); 2) Обеспечить полную герметичность тулчейнов и зависимостей; 3) Развернуть ферму удаленного кэширования (Remote Caching) и распределенного выполнения компиляции (Remote Execution); 4) Интегрировать Change Detection (сборка строго затронутых PR таргетов).</p>\n<p><strong>Пример:</strong></p>\n<pre><code>[ Git Monorepo ] -&gt; [ Target Graph Analyzer ] -&gt; [ Remote Execution Engine ] -&gt; [ Distributed Cache ]\n</code></pre>\n<p><strong>Источник:</strong> <a href=\"https://abseil.io/resources/swe-book?utm_source=gemini\">Software Engineering at Google (Build Systems and Monorepos)</a></p>\n","group":"L4","line":1717}];
